const log=(text)=>{const el=document.createElement('div');el.innerHTML=text;$('#log').prepend(el);while($('#log').children.length>3)$('#log').lastChild.remove()};
function heroUpgradeLevel(id){return state.inventory?.upgrades?.[id]||0}
function scaledHero(h){const level=heroUpgradeLevel(h.id),mult=1+level*.1,hpMult=1+(state.globalHpBonus||0);return {...h,hp:Math.round(h.hp*mult*hpMult),atk:Math.round(h.atk*mult),def:Math.round((h.def||0)*mult),upgradeLevel:level}}
function cloneHero(h){const upgraded=scaledHero(h);return {...upgraded,maxHp:upgraded.hp,hp:upgraded.hp,shield:h.baseShield||0,bonusDamage:0,stars:5,alive:true,skills:h.skills.map(x=>[...x])}}
function applyTeamSynergies(){const tuanzi=state.team.find(h=>h.id==='tuanzi'),zbh=state.team.find(h=>h.id==='zbh'),jiale=state.team.find(h=>h.id==='jiale'),hyb=state.team.find(h=>h.id==='hyb'),lcr=state.team.find(h=>h.id==='lcr');if(tuanzi&&zbh&&!zbh.tuanziBond){zbh.maxHp+=5000;zbh.hp+=5000;zbh.tuanziBond=true}if(jiale&&hyb&&!hyb.jialeBond){hyb.maxHp=Math.round(hyb.maxHp*1.5);hyb.hp=Math.round(hyb.hp*1.5);hyb.atk=Math.round(hyb.atk*1.5);hyb.def=Math.round((hyb.def||0)*1.5);hyb.jialeBond=true}if(lcr)state.team.filter(h=>h.gender==='female'&&!h.lcrBlessing).forEach(h=>{h.maxHp=Math.round(h.maxHp*1.3);h.hp=Math.round(h.hp*1.3);h.atk=Math.round(h.atk*1.3);h.def=Math.round((h.def||0)*1.3);h.lcrBlessing=true})}
const tuanziProtects=target=>target?.id==='zbh'&&state.team.some(h=>h.id==='tuanzi'&&h.alive);
function grantHeroFragments(id,amount=20){state.inventory.fragments??={};state.inventory.upgrades??={};state.inventory.fragments[id]=(state.inventory.fragments[id]||0)+amount;let gained=0;while(state.inventory.fragments[id]>=100){state.inventory.fragments[id]-=100;state.inventory.upgrades[id]=(state.inventory.upgrades[id]||0)+1;gained++}return gained}
function normalizeHeroUpgrades(){state.inventory.fragments??={};state.inventory.upgrades??={};Object.keys(state.inventory.fragments).forEach(id=>{while(state.inventory.fragments[id]>=100){state.inventory.fragments[id]-=100;state.inventory.upgrades[id]=(state.inventory.upgrades[id]||0)+1}})}
const allCampaignStages=()=>campaignChapters.flatMap(c=>c.stages);
const mainStages=chapter=>chapter.stages.filter(s=>!s.optional);
const chapterComplete=chapter=>mainStages(chapter).every(s=>state.cleared.includes(s.id));
const currentStage=()=>RDFZ.getStage(state.currentStageId)||campaignChapters[0].stages[0];
const isBlackoutRound=()=>state.currentStageId==='c1-3'&&state.round%2===0;
const darknessMiss=()=>Math.random()<(isBlackoutRound()?.5:state.currentStageId==='c4-1'?.5:0);
const missRuleLabel=()=>state.currentStageId==='c4-1'?'灌木遮蔽 · 攻击被枝叶完全挡住':'断电中 · 攻击打歪了';
const chapterUnlocked=index=>index===1||chapterComplete(campaignChapters[index-2]);
const stageUnlocked=(chapter,index)=>{const stage=chapter.stages[index];if(!stage||!chapterUnlocked(chapter.index))return false;if(stage.optional)return true;const required=mainStages(chapter),requiredIndex=required.findIndex(s=>s.id===stage.id);return requiredIndex===0||state.cleared.includes(required[requiredIndex-1].id)};
function startDraft(){state.team=[];$('#startScreen').classList.add('hidden');$('#draftScreen').classList.remove('hidden');renderDraft()}
function renderDraft(){const positions=[1,2,3,4,5];$('#draftSlots').innerHTML=positions.map(p=>{const h=state.team.find(x=>x.pos===p);return `<div class="draft-slot ${h?'filled':''}">${p}号位 · ${h?h.name:'待选择'}</div>`}).join('');$('#draftCards').innerHTML=heroes.map(h=>`<button class="draft-card ${state.team.some(x=>x.id===h.id)?'chosen':''}" data-id="${h.id}" style="--c1:${h.c[0]};--c2:${h.c[1]}"><div class="portrait">${h.name[0]}</div><b>${h.rank} · ${h.name}</b><p>【${h.role}】 ${h.pos}号位<br>${h.trait}</p></button>`).join('');$$('.draft-card').forEach(b=>b.onclick=()=>chooseHero(b.dataset.id));$('#enterBattle').disabled=state.team.length<5}
function chooseHero(id){const h=heroes.find(x=>x.id===id);const existing=state.team.findIndex(x=>x.pos===h.pos);if(existing>=0){if(state.team[existing].id===id)state.team.splice(existing,1);else state.team[existing]=cloneHero(h)}else state.team.push(cloneHero(h));state.team.sort((a,b)=>a.pos-b.pos);renderDraft()}
function createEnemies(){const stage=currentStage();if(stage.id==='c2-1'){const boss=heroes.find(h=>h.id==='tuanzi');state.enemies=[{...boss,id:'boss-tuanzi',heroId:'tuanzi',name:'柯基团子',pos:1,rank:'BOSS',role:'玻璃绿植房守护者',maxHp:30000,hp:30000,atk:100,def:0,shield:0,stars:0,alive:true}];return}if(stage.id==='c1-2'){const boss=heroes.find(h=>h.id==='lzy');state.enemies=[{...boss,id:'boss-lsy',heroId:'lzy',name:'李思宇',pos:1,rank:'BOSS',role:'中医守关者',maxHp:60000,hp:60000,atk:2000,def:0,shield:0,regen:.2,stars:0,alive:true}];return}if(stage.id==='c1-4'){const boss=heroes.find(h=>h.id==='hyb');state.enemies=[{...boss,id:'boss-hyb',heroId:'hyb',name:'黄艺博',pos:1,rank:'BOSS',role:'黄犬 · 阶梯教室守关者',maxHp:100000,hp:100000,atk:2000,femaleDamage:7000,maleDamage:2000,def:0,shield:0,stars:0,alive:true}];return}if(stage.id==='c1-5'){const makeBoss=(hero,id,pos,role)=>({...hero,id,heroId:hero.id,pos,rank:'BOSS',role,maxHp:Math.round(hero.hp*1.2),hp:Math.round(hero.hp*1.2),atk:Math.round(hero.atk*1.2),def:Math.round((hero.def||0)*1.2),shield:0,bonusDamage:0,stars:12,alive:true,bossBot:true,skillBoost:1.2});state.enemies=[makeBoss(heroes.find(h=>h.id==='haq'),'boss-haq',1,'镜妆守卫 · 防御逻辑'),makeBoss(heroes.find(h=>h.id==='zbh'),'boss-zbh',3,'五行妆师 · 成长逻辑')];return}const scale=stage.enemyScale||1;state.enemies=enemyTemplates.map((e,i)=>({...e,id:'enemy'+i,pos:i+1,maxHp:Math.round(e.hp*scale),hp:Math.round(e.hp*scale),atk:Math.round(e.atk*scale),shield:0,alive:true,rank:i===0?'S':'A'}))}
