 if(type==='elementShieldGrow'){h.shield+=power;h.bonusDamage=(h.bonusDamage||0)+300;addFloat(h,`护盾 +${power} · 金伤 +300`,'shield');particles(h,'#e9ca70');log(`<b>${h.name}</b> 的金伤永久增加 300`);await wait(300)}
 if(type==='fiveElementGrow'){h.bonusDamage=(h.bonusDamage||0)+power;addFloat(h,`五行伤害 +${power}`,'heal');particles(h,'#70c7ff');log(`<b>${h.name}</b> 五行升华 · 五种属性各增加 400，合计提升 2000`);await wait(320)}
