 if(type==='maxHpUp'){h.maxHp+=power;h.hp+=power;addFloat(h,`生命上限 +${power}`,'heal');particles(h,'#67e8a5');await wait(300)}
 if(type==='selfHealFlat')await heal(h,power);
 if(type==='percentAoe')for(const e of state.enemies.filter(x=>x.alive))await hit(e,Math.max(1,e.hp*power),'damage',h);
