 if(type==='jialeVeil'){const target=findTarget('low'),hpBefore=target?.hp||0,shieldBefore=target?.shield||0;await hit(target,h.atk*power*5,'damage',h,'element');const dealt=Math.max(0,hpBefore-(target?.hp||0))+Math.max(0,shieldBefore-(target?.shield||0));if(target?.alive){target.sealedTurns=1;addFloat(target,'层纱 · 下回合封锁','shield')}h.shield+=Math.round(dealt*.3);addFloat(h,`◈ +${Math.round(dealt*.3)}`,'shield')}
