 if(type==='scxWhiteWolf'){const target=findTarget('low'),percentDamage=Math.round(target.maxHp*.08),totalDamage=h.atk*power+percentDamage,dealt=await piercingHit(target,totalDamage,h);await heal(h,dealt||0);log(`<b>${h.name}</b> 的白狼造成 700% 攻击并附加目标最大生命 8%（${percentDamage}）的无视护盾伤害，将实际伤害 ${dealt||0} 全额转化为生命`)}
 if(type==='yxzNap'){await heal(h,h.maxHp*power);log(`<b>${h.name}</b> 补完一场回笼觉，恢复 25% 最大生命`)}
 if(type==='yxzHibernate'){await heal(h,h.maxHp*power);h.hibernateTurns=2;addFloat(h,'持续恢复 · 2回合','heal');log(`<b>${h.name}</b> 进入深绿休眠，接下来两回合持续恢复生命`)}
 if(type==='yxzRebirth'){h.maxHp+=power;h.hp+=power;await heal(h,h.maxHp*.6);addFloat(h,'生命上限 +20000','heal');particles(h,'#73c98b');log(`<b>${h.name}</b> 展开宅域，本局生命上限提升并恢复 60% 最大生命`)}
 if(type==='younTear'){const target=state.team.filter(x=>x.alive&&x.id!==h.id).sort((a,b)=>(b.atk+(b.bonusDamage||0))-(a.atk+(a.bonusDamage||0)))[0]||h;target.damageAmpUntil=state.round+2;addFloat(target,'泪 · 伤害×2','heal');particles(target,'#ba6cff');log(`<b>${h.name}</b> 为 ${target.name} 附加「泪」：基础与属性伤害翻倍，持续两回合`);await wait(320)}
 if(type==='younShield'){for(const ally of state.team.filter(x=>x.alive)){const gain=Math.round(ally.hp);ally.shield+=gain;addFloat(ally,`◈ +${gain}`,'shield')}particles(h,'#c589ff');log(`<b>${h.name}</b> 施放「xp」：全队获得等于当前生命100%的护盾`);await wait(360);render()}
 if(type==='lykBoar'){const target=state.enemies.filter(x=>x.alive).sort((a,b)=>b.hp-a.hp)[0];await hit(target,h.atk*power,'damage',h);h.shield+=15000;addFloat(h,'◈ +15000','shield');log(`<b>${h.name}</b> 以「野猪」撞开阵线并获得15000护盾`)}
 if(type==='lykAssault'){h.guardUntil=state.round+2;h.currentAttackIsAoe=true;for(const e of state.enemies.filter(x=>x.alive))await hit(e,h.atk*power,'damage',h);h.currentAttackIsAoe=false;addFloat(h,'固守 · 2回合','shield');log(`<b>${h.name}</b> 发动「突击」，两回合内承受的群伤转移量降低30%`)}
