async function bossBotAction(e){const players=state.team.filter(x=>x.alive).sort((a,b)=>a.pos-b.pos),allies=state.enemies.filter(x=>x.alive),boost=e.skillBoost||1;if(!players.length)return;const cast=async(name,cost,action)=>{e.stars-=cost;log(`<b>${e.name}</b> 按规则施放「${name}」`);await action()};if(e.heroId==='haq'){const wounded=allies.some(x=>x.hp/x.maxHp<.45);if(wounded&&e.stars>=5)return cast('namina',5,async()=>{for(const ally of allies)await heal(ally,ally.maxHp*.3*boost)});if(e.shield<e.maxHp*.5&&e.stars>=8)return cast('刘海护体',8,async()=>{const gain=Math.round(e.maxHp*2*boost);e.shield+=gain;addFloat(e,`◈ +${gain}`,'shield');particles(e,'#66c9ff');await wait(300);render()});if(e.stars>=5)return cast('高冷',5,async()=>{let total=0;for(const target of players.filter(x=>x.alive)){const damage=Math.round(e.atk*3*boost);total+=damage;await enemyHit(target,damage)}e.shield+=total;addFloat(e,`◈ +${total}`,'shield');render()})}if(e.heroId==='zbh'){if((e.bonusDamage||0)<2000*boost&&e.stars>=12)return cast('五行升华',12,async()=>{const gain=Math.round(2000*boost);e.bonusDamage=(e.bonusDamage||0)+gain;addFloat(e,`五行伤害 +${gain}`,'heal');particles(e,'#70c7ff');await wait(320);render()});if(e.shield<e.maxHp*.5&&e.stars>=6)return cast('固若金汤',6,async()=>{const shield=Math.round(5000*boost),gain=Math.round(300*boost);e.shield+=shield;e.bonusDamage=(e.bonusDamage||0)+gain;addFloat(e,`护盾 +${shield} · 金伤 +${gain}`,'shield');particles(e,'#e9ca70');await wait(300);render()});if(e.stars>=5)return cast('甘霖水',5,async()=>{await enemyHit(players[0],Math.round((e.atk+(e.bonusDamage||0))*4*boost));const gain=Math.round(100*boost);e.bonusDamage=(e.bonusDamage||0)+gain;addFloat(e,`水伤 +${gain}`,'heal');render()})}const target=players[0];log(`<b>${e.name}</b> 星能不足，执行普通攻击`);await enemyHit(target,e.atk)}
const standardBossBotAction=bossBotAction;
bossBotAction=async function(e){
 const players=state.team.filter(x=>x.alive).sort((a,b)=>a.hp-b.hp),boost=e.skillBoost||1;
 if(e.heroId==='jiale'){
  const veilFactor=e.mutinyJiale?5:200,lotusFactor=e.mutinyJiale?3:100;
  const free=state.round<=(e.freeSkillUntilRound||0);
  if(!free&&e.stars>=10){e.stars-=10;e.freeSkillUntilRound=state.round+2;log('<b>珈乐</b> 按规则施放「乐邦战士」· 两回合技能免耗');return}
  if(free||e.stars>=7){if(!free)e.stars-=7;const target=players[0];log('<b>珈乐</b> 按规则施放「层纱」');const before=target.hp;await enemyHit(target,e.atk*veilFactor*5);if((target.stealthTurns||0)<=0)target.sealedTurns=1;const dealt=Math.max(0,before-target.hp);e.shield+=Math.round(dealt*.3);addFloat(e,`◈ +${Math.round(dealt*.3)}`,'shield');return}
  if(e.stars>=5){e.stars-=5;log('<b>珈乐</b> 按规则施放「骨生白莲」');for(const target of players.slice(0,3))await enemyHit(target,e.atk*lotusFactor*5);return}
 }
 if(e.heroId==='zbh'){
  if((e.bonusDamage||0)<2000*boost&&e.stars>=12){e.stars-=12;const gain=Math.round(2000*boost);e.bonusDamage=(e.bonusDamage||0)+gain;addFloat(e,`五行伤害 +${gain}`,'heal');log(`<b>祖碧晗</b> 施放「五行升华」· 总属性伤害提升 ${gain}`);return}
  if(e.shield<e.maxHp*.5&&e.stars>=6){e.stars-=6;const shield=Math.round(5000*boost),gain=Math.round(300*boost);e.shield+=shield;e.bonusDamage=(e.bonusDamage||0)+gain;addFloat(e,`护盾 +${shield} · 金伤 +${gain}`,'shield');return}
  if(e.stars>=5){e.stars-=5;const damage=Math.round((e.atk+(e.bonusDamage||0))*4*boost);log(`<b>祖碧晗</b> 施放「甘霖水」·（基础伤害＋属性伤害）×4 = ${damage}`);await enemyHit(players[0],damage);e.bonusDamage=(e.bonusDamage||0)+Math.round(100*boost);return}
 }
 if(e.heroId==='youn'){
  const allies=state.enemies.filter(x=>x.alive),carry=allies.filter(x=>x.id!==e.id).sort((a,b)=>(b.atk+(b.bonusDamage||0))-(a.atk+(a.bonusDamage||0)))[0];
  if(allies.some(x=>(x.shield||0)<x.hp*.35)&&e.stars>=6){e.stars-=6;log('<b>柚恩</b> 按规则施放「xp」');for(const ally of allies){const gain=Math.round(ally.hp);ally.shield+=gain;addFloat(ally,`◈ +${gain}`,'shield')}render();return}
  if(carry&&e.stars>=7&&carry.damageAmpUntil<state.round+1){e.stars-=7;carry.damageAmpUntil=state.round+2;log(`<b>柚恩</b> 按规则施放「泪」· ${carry.name} 基础与属性伤害翻倍两回合`);addFloat(carry,'泪 · 伤害×2','heal');return}
 }
 if(e.heroId==='lyk'){
  if(e.hp/e.maxHp<.45&&e.stars>=9){e.stars-=9;e.maxHp+=20000;e.hp=Math.min(e.maxHp,e.hp+Math.round(e.maxHp*.5));e.shield+=30000;log('<b>凌艺坤</b> 按规则施放「鲲」· 扩充生命并重整防线');render();return}
  if(e.stars>=6){e.stars-=6;e.guardUntil=state.round+2;log('<b>凌艺坤</b> 按规则施放「突击」· 群体火力压制并进入固守');await enemyGroupHit(e.atk*1.8,'抵抗军突击');return}
  if(e.stars>=4){e.stars-=4;const target=players.sort((a,b)=>b.hp-a.hp)[0];log('<b>凌艺坤</b> 按规则施放「野猪」');await enemyHit(target,e.atk*3);e.shield+=15000;render();return}
 }
 if(e.heroId==='lcr'){
  if(e.stealthTurns>0){e.stealthTurns--;log(`<b>李承容</b> 藏身魅影，本回合不行动 · 剩余 ${e.stealthTurns}`);return}
  const target=players[0];
  if(e.hp/e.maxHp<.45&&e.stars>=5&&state.round>(e.stealthCooldownUntil||0)){e.stars-=5;e.stealthTurns=2;e.stealthCooldownUntil=state.round+5;log('<b>李承容</b> 察觉致命威胁，施放「魅影」进入两回合无敌隐身');return}
  if(e.stars>=7&&(target.hp/target.maxHp<.5||target.hp-e.atk*6*boost<target.maxHp*.2)){e.stars-=7;log('<b>李承容</b> 按规则施放「失败的王」');await enemyHit(target,e.atk*6*boost);if(target.alive&&target.hp/target.maxHp<.2){target.hp=0;target.alive=false;addFloat(target,'斩杀','damage');render()}return}
  if(e.stars>=4){e.stars-=4;log('<b>李承容</b> 按规则施放「容诗」');await enemyHit(target,e.atk*3*boost);return}
 }
 return standardBossBotAction(e)
};
async function finalBossAction(e){const targets=state.team.filter(x=>x.alive).sort((a,b)=>a.pos-b.pos);if(!targets.length)return;if(e.phase===2){log('<b>神秘学姐</b> 释放全域数据震荡');await enemyGroupHit(2000,'全域数据震荡');return}const target=targets[0];log(e.phase===1?'<b>神秘学姐</b> 以屏障脉冲发动攻击':'<b>神秘学姐</b> 锁定单体执行清除');await enemyHit(target,e.phase===3?7000:5000)}
async function showPersimmonWarning(){const fx=document.createElement('div');fx.className='persimmon-doom';fx.innerHTML='<i>⚠</i><b>致命柿子雨</b><span>大量落果正在锁定全队</span>';document.body.append(fx);state.team.filter(x=>x.alive).forEach(x=>particles(x,'#ff7a18'));await wait(850);fx.classList.add('fade');setTimeout(()=>fx.remove(),500)}
