async function enemyHit(target,amount){if(target.stealthTurns>0){addFloat(target,'魅影 · 无效','shield');log(`<b>${target.name}</b> 在魅影中免疫伤害与负面效果`);await wait(300);return 0}if(tuanziProtects(target)){addFloat(target,'无敌 · 团子守护','shield');log('<b>团子守护</b> 为祖碧晗抵消了本次伤害');await wait(330);return 0}amount=Math.round(amount);let absorbed=Math.min(target.shield,amount);target.shield-=absorbed;let real=amount-absorbed;target.hp-=real;RDFZ.emit('combatImpact',{amount,absorbed,kind:'physical'});const el=document.querySelector(`[data-id="${target.id}"]`);el?.classList.add('hit');addFloat(target,absorbed?`-${real}  ◈${absorbed}`:`-${real}`,'damage');particles(target,'#f24d63');await wait(330);el?.classList.remove('hit');if(target.hp<=0){if(target.id==='youn'&&!target.spiritUsed){target.spiritUsed=true;target.spiritTurns=10;target.hp=1;target.alive=true;addFloat(target,'灵体 · 10回合','shield');log('<b>柚恩</b> 受到致命伤害，进入灵体状态并锁定为1点生命')}else{target.hp=0;target.alive=false;log(`<b>${target.name}</b> 失去战斗能力`)}}render();return real}
const resolveEnemyHit=enemyHit;
enemyHit=async function(target,...args){if((target?.guaranteedDodges||0)>0){target.guaranteedDodges--;addFloat(target,'赤兔疾影 · 闪避','shield');log(`<b>${target.name}</b> 骑赤兔马闪过了本次攻击`);await wait(300);return 0}const dodge=target?.id==='lsy'&&state.currentStageId==='c4-3'?.9:(target?.dodgeChance||0);if(dodge&&Math.random()<dodge){addFloat(target,`闪避 ${Math.round(dodge*100)}%`,'shield');log(`<b>${target.name}</b> 触发赤兔疾影 · 完全闪避伤害`);await wait(300);return 0}if(target?.flying){addFloat(target,'飞行 · 无敌','shield');log(`<b>${target.name}</b> 在飞行状态中免疫本次伤害`);await wait(300);return 0}return resolveEnemyHit(target,...args)};
const hitBeforeYounSpirit=hit;
hit=async function(target,...args){if(target?.spiritTurns>0){target.hp=1;addFloat(target,'灵体 · 锁血','shield');await wait(260);return 0}return hitBeforeYounSpirit(target,...args)};
const enemyHitBeforeYounSpirit=enemyHit;
enemyHit=async function(target,...args){if(target?.spiritTurns>0){target.hp=1;addFloat(target,'灵体 · 锁血','shield');log(`<b>${target.name}</b> 的灵体状态锁定生命为1`);await wait(260);return 0}return enemyHitBeforeYounSpirit(target,...args)};
const enemyHitBeforeZyfGrit=enemyHit;
enemyHit=async function(target,...args){const dealt=await enemyHitBeforeZyfGrit(target,...args);if(target?.id==='zyf'&&target.alive&&!target.gritUsed&&target.hp/target.maxHp<.3){target.gritUsed=true;target.hp=Math.min(target.maxHp,target.hp+Math.round(target.maxHp*.2));target.shield+=10000;addFloat(target,'不泄气 · 生命20% / 护盾10000','heal');log('<b>张一凡</b> 触发「不泄气」，重新站稳阵线');render()}return dealt};
const enemyHitBeforeSskNuke=enemyHit;
enemyHit=async function(target,...args){const dealt=await enemyHitBeforeSskNuke(target,...args);if(target?.id==='ssk'&&!target.alive)await triggerSskNuke(target);return dealt};
const hitBeforeLykGuard=hit;
hit=async function(target,amount,type='damage',source=null,kind='physical'){const leader=state.enemies.find(e=>e.heroId==='lyk'&&e.alive);if(leader&&source?.currentAttackIsAoe&&state.enemies.includes(target)){addFloat(target,'抵抗阵线 · 免疫','shield');const ratio=leader.guardUntil>=state.round?.35:.5,dealt=await hitBeforeLykGuard(leader,amount*ratio,type,source,kind);log(`<b>凌艺坤</b> 拦截群伤，替 ${target.name} 承受 ${Math.round(amount*ratio)} 点转移伤害`);return dealt}return hitBeforeLykGuard(target,amount,type,source,kind)};
const hitBeforeSeniorSskNuke=hit;
hit=async function(target,...args){const dealt=await hitBeforeSeniorSskNuke(target,...args);if(target?.sskSeniorBoss&&!target.alive&&!target.nukeTriggered){target.nukeTriggered=true;log('<b>史绍恺Boss · 最终论文</b> · 死亡核爆削减我方每名成员40%当前生命');for(const hero of state.team.filter(x=>x.alive))await enemyHit(hero,Math.max(1,Math.round(hero.hp*.4)))}return dealt};
async function enemyGroupHit(amount,label='群体攻击'){const living=state.team.filter(x=>x.alive),leader=living.find(x=>x.id==='lyk');if(!leader){for(const target of living)await enemyHit(target,amount);return}const ratio=state.currentStageId==='c9-7'?.05:leader.guardUntil>=state.round?.35:.5,transfer=Math.round(amount*living.length*ratio);log(state.currentStageId==='c9-7'?`<b>抵抗阵线异常共鸣</b> · ${label}被凌艺坤截断，伤害汇聚发生异常衰减`:`<b>抵抗阵线</b> · ${label}无法伤害队友，群伤总额的${Math.round(ratio*100)}%（${transfer}）转移给凌艺坤`);living.filter(x=>x.id!=='lyk').forEach(x=>addFloat(x,'群伤免疫','shield'));await enemyHit(leader,transfer)}
let soulsCollected=0;
function renderSoulField(){const left=12-soulsCollected;$('#soulCount').textContent=`${soulsCollected} / 12`;$('#soulField').innerHTML=Array.from({length:Math.min(6,left)},()=>`<button class="soul-orb" aria-label="收集游魂" style="--x:${8+Math.random()*82}%;--y:${18+Math.random()*65}%;--d:${4+Math.random()*4}s;--delay:${-Math.random()*4}s"><i></i></button>`).join('');$$('.soul-orb').forEach(b=>b.onclick=()=>{b.disabled=true;b.classList.add('captured');soulsCollected++;if(soulsCollected>=12)setTimeout(startGhostKingPhase,420);else setTimeout(renderSoulField,160)})}
function openSoulHunt(){state.started=false;state.busy=true;soulsCollected=0;$('#app').classList.add('hidden');$('#soulHuntScreen').classList.remove('hidden');renderSoulField()}
function startGhostKingPhase(){$('#soulHuntScreen').classList.add('hidden');$('#app').classList.remove('hidden');state.specialPhase=3;rebuildBattleTeam(12);createEnemies();state.round=1;state.selected=0;state.damage=0;state.started=true;state.busy=false;state.paused=false;render();log('<b>阶段三</b> · 魂魄汇聚成无法消灭的鬼王。承受固定 7000 伤害，坚持 20 回合！');save()}
let finalEpiloguePending=false;
function checkEnd(){if(!state.enemies.some(x=>x.alive)){if(state.currentStageId==='c7-2'&&(state.footballWave||1)===1){state.footballWave=2;createEnemies();log('<b>第二波</b> · 又有五名AI足球队员冲入球场！');render();return true}if(state.currentStageId==='c2-6'&&state.specialPhase===1){openSoulHunt();return true}if(state.currentStageId==='c1-6')finalEpiloguePending='final';if(state.currentStageId==='c5-4')finalEpiloguePending='libraryDog';if(state.currentStageId==='c6-4')finalEpiloguePending='reportHall';showResult(true);if(finalEpiloguePending)$('#nextBtn').textContent='观看战后演出';return true}if(!state.team.some(x=>x.alive)){showResult(false);return true}return false}
function showResult(win){state.busy=true;const stage=currentStage(),reward=stage.rewards?.gems||120,isFirst=win&&!state.cleared.includes(stage.id);let recruited=null;if(isFirst){state.cleared.push(stage.id);state.gems+=reward}const stageRecruit={"c1-2":'lzy',"c1-4":'hyb',"c2-1":'tuanzi',"c2-2":'jiale',"c2-4":'lcr'},rewardHero=stageRecruit[stage.id];if(win&&rewardHero&&!state.owned.includes(rewardHero)){state.owned.push(rewardHero);recruited=rewardHero}const recruitedHero=heroes.find(h=>h.id===recruited);$('#resultScreen').classList.remove('hidden');$('#resultEyebrow').textContent=win?'BATTLE COMPLETE':'TACTICAL FAILURE';$('#resultTitle').textContent=win?'演算胜利':'演算失败';$('#resultText').textContent=win?(recruitedHero?`击败${stage.name}守关者，${recruitedHero.name}已加入伙伴队伍！`:'新道路已经解锁，返回章节地图继续探索。'):'重新调整阵容与技能释放时机，再来一次。';$('#resultStats').innerHTML=`<div><span>战斗回合</span><b>${state.round}</b></div><div><span>累计伤害</span><b>${Math.round(state.damage/100)/10}k</b></div><div><span>${recruitedHero?'新伙伴':win?'通关奖励':'存活队员'}</span><b>${recruitedHero?recruitedHero.name:win?(isFirst?'◆ '+reward:'已领取'):state.team.filter(x=>x.alive).length}</b></div>`;$('#nextBtn').style.display=win?'inline-block':'none';$('#nextBtn').textContent='返回章节地图';RDFZ.emit('stageComplete',{chapter:state.chapter,stageId:stage.id,win,recruited,firstClear:isFirst});save()}
const checkEndWithFootballWave=checkEnd;
function startMutinyPhase2(){state.specialPhase=2;state.team=[{...cloneHero(heroes.find(h=>h.id==='jiale')),pos:3,stars:12}];createEnemies();state.round=1;state.selected=0;state.damage=0;state.started=true;state.busy=false;state.paused=false;$('#app').classList.remove('hidden');$('#turnLabel').textContent='我方行动';render();log('<b>内讧 · 第二阶段</b> · 使用珈乐击败被AI夺舍的强化何安淇');save()}
checkEnd=function(){if(state.currentStageId==='c8-6'&&state.specialPhase===1&&!state.enemies.some(x=>x.alive)){state.started=false;state.busy=true;openStageNarrative('pre','juniorPossession');return true}if(state.currentStageId==='c7-2'&&!state.enemies.some(x=>x.alive)&&(state.footballWave||1)===1){state.footballWave=2;createEnemies();state.round++;state.busy=false;$('#turnLabel').textContent='我方行动';log('<b>第二波</b> · 又有五名AI足球队员冲入球场！');render();save();return true}return checkEndWithFootballWave()};
const showResultBeforeGarden=showResult;
showResult=function(win){if(win&&state.currentStageId==='c4-2'&&!state.owned.includes('lsy'))state.owned.push('lsy');if(win&&state.currentStageId==='c6-4'&&!state.owned.includes('youn'))state.owned.push('youn');if(win&&state.currentStageId==='c7-3'&&!state.owned.includes('lyk'))state.owned.push('lyk');if(win&&state.currentStageId==='c8-3'&&!state.owned.includes('xzh'))state.owned.push('xzh');showResultBeforeGarden(win);if(win&&state.currentStageId==='c4-2')$('#resultText').textContent='刘树苡摆脱AI控制，A级伙伴「刘树苡」已加入队伍。';if(win&&state.currentStageId==='c4-4')$('#resultText').textContent='古树失去神智，中心花园恢复正常。';if(win&&state.currentStageId==='c6-4')$('#resultText').textContent='何安淇稳定了柚恩的灵体，S级伙伴「柚恩」已加入队伍。';if(win&&state.currentStageId==='c7-3')$('#resultText').textContent='误会解除。抵抗军首领凌艺坤确认小队并未投靠AI，A级伙伴「凌艺坤」加入队伍。';if(win&&state.currentStageId==='c8-3')$('#resultText').textContent='徐子瀚的抽取链路被切断，S级伙伴「徐子瀚」加入队伍。';if(win&&state.currentStageId==='c8-6')$('#resultText').textContent='珈乐击败了被夺舍的何安淇。内讧结束，但AI仍在更高处等待。'};
const showResultBeforeSenior=showResult;
showResult=function(win){
 const seniorRewards={
  'c9-1':[['pyh'],'彭遗憾在地下球场找回了自己的好胜心。A级伙伴「彭遗憾」已加入队伍。'],
  'c9-2':[['nailin','qmr'],'落地窗前的控制链路被击碎。A级伙伴「乃琳」与「秦敏然」已加入队伍。'],
  'c9-5':[['ruishou','ssk'],'核反应被压制，五层连廊恢复平静。A级伙伴「瑞兽」与「史绍恺」已加入队伍。']
 };
 const reward=win&&seniorRewards[state.currentStageId];
 if(reward)for(const id of reward[0])if(!state.owned.includes(id))state.owned.push(id);
 showResultBeforeSenior(win);
 if(reward)$('#resultText').textContent=reward[1];
};
function rebuildBattleTeam(stars=5){state.team=state.team.map((x,i)=>({...cloneHero(heroes.find(h=>h.id===x.id)),pos:i+1,stars}));applyTeamSynergies()}
function returnToChapterAfterBattle(){$('#resultScreen').classList.add('hidden');state.started=false;state.busy=false;$('#app').classList.add('hidden');openChapterMap(state.chapter)}
function nextStage(){if(finalEpiloguePending){const scenario=finalEpiloguePending;finalEpiloguePending=false;$('#resultScreen').classList.add('hidden');openStageNarrative('post',scenario);return}returnToChapterAfterBattle()}
function retry(){rebuildBattleTeam();$('#resultScreen').classList.add('hidden');createEnemies();state.round=1;state.selected=0;state.busy=false;state.damage=0;state.started=true;$('#turnLabel').textContent='我方行动';if(state.currentStageId==='c6-1')state.team.forEach(h=>h.shield=0);rollFlightState();render();if(state.currentStageId==='c6-2')spawnLambSoup();log('<b>重新演算</b> · 队伍状态已恢复')}
function save(){const teamIds=state.savedTeamIds.length?state.savedTeamIds:state.team.map(x=>x.id);const snapshot={...state,team:teamIds};localStorage.setItem('rdfz-save',JSON.stringify({chapter:state.chapter,team:teamIds}));localStorage.setItem('rdfz-profile',JSON.stringify(snapshot));RDFZDB.saveState(snapshot).then(showSaved).catch(console.error)}
function showSaved(){let b=$('.save-badge');if(!b){b=document.createElement('div');b.className='save-badge';b.textContent='✓ 进度已保存到本机数据库';document.body.append(b)}b.classList.add('show');clearTimeout(showSaved.t);showSaved.t=setTimeout(()=>b.classList.remove('show'),1500)}
async function loadProfile(){let p;try{p=await RDFZDB.loadState()}catch(e){console.warn('IndexedDB unavailable',e)}if(!p){try{p=JSON.parse(localStorage.getItem('rdfz-profile'))}catch{}}if(p){state.chapter=p.chapter||1;state.currentStageId=allCampaignStages().some(s=>s.id===p.currentStageId)?p.currentStageId:'c1-1';state.gems=p.gems??RDFZGameConfig.initialGems;state.pity=p.pity??30;state.owned=p.owned||['haq'];state.savedTeamIds=(p.team||[]).filter(id=>typeof id==='string');state.firstTen=p.firstTen??true;state.tutorialDone=p.tutorialDone??false;state.globalHpBonus=p.globalHpBonus||0;state.inventory=p.inventory||state.inventory;state.inventory.fragments??={};state.inventory.upgrades??={};normalizeHeroUpgrades();state.cleared=p.cleared||[];state.storySeen=p.storySeen||[]}// Build configuration controls the mode, never a saved debug flag.
state.unlimitedGems=RDFZGameConfig.unlimitedGems;
// An old infinite/debug balance has no meaningful earned value. Reset only currency;
// retain heroes, upgrades and progression. Subsequent normal loads preserve earnings.
if(!state.unlimitedGems&&p?.unlimitedGems)state.gems=RDFZGameConfig.initialGems;
if(!p||p.unlimitedGems!==state.unlimitedGems||p.gems!==state.gems)save();
updateHub()}
async function showHome(){await saveResetReady;await loadProfile();$('#startScreen').classList.add('hidden');$('#resultScreen').classList.add('hidden');$('#homeScreen').classList.remove('hidden');$('#app').classList.add('hidden');state.started=false;updateHub();if(!state.tutorialDone)openTutorial()}
function updateHub(){$('#gems').textContent=state.unlimitedGems?'∞':state.gems;$('#pityCount').textContent=state.pity;$('#ownedCount').textContent=`${state.owned.length} / ${heroes.length}`;const stage=currentStage(),card=$('.chapter-card');if(card)card.innerHTML=`<small>当前关卡</small><b>${stage.chapter}-${stage.index} ${stage.name}</b><span>推荐战力 ${Math.round(11000*stage.enemyScale).toLocaleString()}</span>`}
function openSummon(){$('#homeScreen').classList.add('hidden');$('#summonScreen').classList.remove('hidden');$('#summonResult').classList.add('hidden');updateHub()}
function autoBuildTeam(){const pool=state.owned.map(id=>heroes.find(h=>h.id===id)).filter(Boolean);const chosen=[];for(const pos of [1,2,3,4,5]){const options=pool.filter(h=>h.pos===pos).sort((a,b)=>(b.rank==='S')-(a.rank==='S'));if(options[0])chosen.push(cloneHero(options[0]))}for(const h of pool){if(chosen.length>=5)break;if(!chosen.some(x=>x.id===h.id))chosen.push(cloneHero(h))}state.team=chosen.slice(0,5).map((h,i)=>({...h,pos:i+1}));return state.team.length===5}
let formationSelection=[];
function startAdventure(){openCampaignMap()}
function openCampaignMap(){$('#homeScreen').classList.add('hidden');$('#chapterMapScreen').classList.add('hidden');$('#campaignMapScreen').classList.remove('hidden');const required=campaignChapters.flatMap(mainStages),total=required.length,done=required.filter(s=>state.cleared.includes(s.id)).length;$('#campaignProgress').textContent=`${done} / ${total}`;$('#campaignMap').innerHTML=campaignChapters.map(c=>{const unlocked=chapterUnlocked(c.index),complete=chapterComplete(c),requiredStages=mainStages(c),cleared=requiredStages.filter(s=>state.cleared.includes(s.id)).length,hasSpecial=c.stages.some(s=>s.optional);return `<button class="chapter-node ${unlocked?'':'locked'} ${complete?'complete':''}" data-chapter="${c.index}" ${unlocked?'':'disabled'}><span class="node-no">CHAPTER ${String(c.index).padStart(2,'0')}</span><span class="node-status">${complete?'✓':unlocked?'→':'锁'}</span><b>${c.name}</b><small>${unlocked?`${cleared} / ${requiredStages.length} 主线${hasSpecial?' · 含特殊关卡':''}`:'完成上一章节后解锁'}</small></button>`}).join('');$$('.chapter-node:not(.locked)').forEach(b=>b.onclick=()=>openChapterMap(+b.dataset.chapter))}
function openChapterMap(chapterIndex){const c=campaignChapters[chapterIndex-1];if(!c||!chapterUnlocked(chapterIndex))return;state.chapter=chapterIndex;$('#campaignMapScreen').classList.add('hidden');$('#homeScreen').classList.add('hidden');$('#chapterMapScreen').classList.remove('hidden');$('#chapterNumber').textContent=`CHAPTER ${String(c.index).padStart(2,'0')}`;$('#chapterMapTitle').textContent=c.name;$('#chapterMapCopy').textContent=c.copy;const required=mainStages(c),done=required.filter(s=>state.cleared.includes(s.id)).length;$('#chapterProgress').textContent=`${done} / ${required.length} 主线`;$('#stagePath').innerHTML=c.stages.map((s,i)=>{const unlocked=stageUnlocked(c,i),complete=state.cleared.includes(s.id),label=s.optional?'SPECIAL':`${c.index}-${s.index}`,status=complete?'· 已通关':unlocked?'· 可挑战':'· 未解锁';return `<button class="stage-node ${s.optional?'optional':''} ${unlocked?'':'locked'} ${complete?'complete':''}" data-stage="${s.id}" ${unlocked?'':'disabled'}><span>${label} ${status}</span><b>${s.name}</b><small>${s.optional?'可跳过 · 不影响后续章节解锁':`推荐战力 ${Math.round(11000*s.enemyScale).toLocaleString()}`}</small><em class="stage-reward">◆ ${s.rewards.gems}</em></button>`}).join('');$$('.stage-node:not(.locked)').forEach(b=>b.onclick=()=>selectCampaignStage(b.dataset.stage))}
