let narrativeMode='pre',narrativeScenario='final',narrativeIndex=0;
function openStageNarrative(mode,scenario='final'){narrativeMode=mode;narrativeScenario=scenario;narrativeIndex=0;$('#chapterMapScreen').classList.add('hidden');$('#app').classList.add('hidden');$('#stageNarrative').classList.remove('hidden');renderStageNarrative()}
function renderStageNarrative(){const lines=stageNarratives[narrativeScenario][narrativeMode],line=lines[narrativeIndex],poster=$('#narrativePoster');$('#narrativeEyebrow').textContent=narrativeScenario==='garden'?'SKY GARDEN · 诱导信号':narrativeScenario==='libraryDog'?(narrativeMode==='pre'?'LISTENING LAB · 全域控制':'ORGANIC CORE · 能量样本'):narrativeScenario==='juniorMutiny'?'JUNIOR BUILDING · 内讧':narrativeScenario==='juniorPossession'?'AI POSSESSION · 第二阶段':narrativeScenario==='windowHall'?'WINDOW HALL · 荒唐宣言':narrativeScenario==='physicsOffice'?'PHYSICS OFFICE · 空置讲台':narrativeScenario==='seniorCafe'?'CAFÉ · 真相对谈':narrativeScenario==='adminFinal'?(narrativeMode==='pre'?'ADMIN FINAL · RSI真相':'EPILOGUE · 风云终章'):narrativeMode==='pre'?'FINAL STAIRWAY · 作战前':'AFTERMATH · 战后演出';$('#narrativeSpeaker').textContent=line[0];$('#narrativeText').textContent=line[1];$('#narrativeProgress').textContent=`${narrativeIndex+1} / ${lines.length}`;$('#nextNarrative').textContent=narrativeIndex===lines.length-1?(narrativeScenario==='juniorPossession'?'珈乐迎战':narrativeScenario==='seniorCafe'?'结束对谈':narrativeMode==='pre'?'进入排兵布阵':'返回章节地图'):'继续';poster.classList.toggle('hidden',!line[2]);RDFZAssets.background(poster,line[2]).then(ok=>{if(ok&&!$('#stageNarrative').classList.contains('hidden')&&stageNarratives[narrativeScenario][narrativeMode]?.[narrativeIndex]===line)RDFZAssets.prefetch(lines[narrativeIndex+1]?.[2])})}
function completeSeniorCafe(){const stage=RDFZ.getStage('c9-8');if(!state.cleared.includes(stage.id)){state.cleared.push(stage.id);state.gems+=stage.rewards?.gems||120;grantPostJuniorHp(stage)}save();$('#stageNarrative').classList.add('hidden');openChapterMap(9)}
function advanceStageNarrative(){const lines=stageNarratives[narrativeScenario][narrativeMode];if(++narrativeIndex<lines.length){renderStageNarrative();return}$('#stageNarrative').classList.add('hidden');if(narrativeScenario==='juniorPossession'){startMutinyPhase2();return}if(narrativeScenario==='seniorCafe'){completeSeniorCafe();return}if(narrativeMode==='pre'){if(narrativeScenario==='basketball')openBasketballGame('c3-4');else openFormation()}else returnToChapterAfterBattle()}
let basketballState={stageId:'',mode:'shot',attempts:0,hits:0,misses:0,pos:0,dir:1,locked:false,raf:0,timer:0};
function openBasketballGame(stageId){state.currentStageId=stageId;state.chapter=3;$('#chapterMapScreen').classList.add('hidden');$('#stageNarrative').classList.add('hidden');$('#basketballGame').classList.remove('hidden');basketballState={stageId,mode:stageId==='c3-3'?'reaction':stageId==='c3-4'?'duel':'shot',attempts:0,hits:0,misses:0,pos:0,dir:1,locked:false,raf:0,timer:0};const reaction=basketballState.mode==='reaction';$('#shotGame').classList.toggle('hidden',reaction);$('#reactionGame').classList.toggle('hidden',!reaction);$('#basketballTitle').textContent=reaction?'中圈争夺':basketballState.mode==='duel'?'终场哨声 · 单挑郭俊游':'三分线';$('#basketballCopy').textContent=reaction?'观察持球者的突破方向，快速点击相同方向完成抢断。':'观察移动指针，在中央绿色区域点击投篮；五次机会命中三球即可过关。';$('#basketballFeedback').textContent=reaction?'连续完成6次正确抢断，失误达到3次将重新开始。':'把握出手时机。';updateBasketballScore();if(reaction)nextReaction();else animateShot()}
function animateShot(){cancelAnimationFrame(basketballState.raf);const tick=()=>{if($('#basketballGame').classList.contains('hidden')||basketballState.mode==='reaction')return;basketballState.pos+=basketballState.dir*1.45;if(basketballState.pos>=100||basketballState.pos<=0)basketballState.dir*=-1;$('#shotNeedle').style.left=`${Math.max(0,Math.min(99,basketballState.pos))}%`;basketballState.raf=requestAnimationFrame(tick)};tick()}
function updateBasketballScore(){$('#basketballScore').textContent=basketballState.mode==='reaction'?`抢断 ${basketballState.hits} / 6 · 失误 ${basketballState.misses} / 3`:`命中 ${basketballState.hits} / 3 · 出手 ${basketballState.attempts} / 5`}
function shootBasketball(){if(basketballState.locked)return;basketballState.locked=true;basketballState.attempts++;const margin=basketballState.mode==='duel'?5:8,hit=Math.abs(basketballState.pos-50)<=margin;if(hit)basketballState.hits++;$('#basketballFeedback').textContent=hit?'空心入网！':'篮球弹框而出。';$('#shotGame').classList.add('shot-made');setTimeout(()=>$('#shotGame').classList.remove('shot-made'),360);updateBasketballScore();setTimeout(()=>{if(basketballState.hits>=3)return finishBasketballGame();if(basketballState.attempts>=5){basketballState.attempts=0;basketballState.hits=0;$('#basketballFeedback').textContent='本轮未能命中三球，再试一次。';updateBasketballScore()}basketballState.locked=false},650)}
function nextReaction(){clearTimeout(basketballState.timer);const dirs=['↑','←','↓','→'];basketballState.target=dirs[Math.floor(Math.random()*4)];$('#reactionPrompt').textContent=basketballState.target;basketballState.timer=setTimeout(()=>resolveReaction(''),1800)}
function resolveReaction(dir){if(basketballState.locked)return;basketballState.locked=true;clearTimeout(basketballState.timer);if(dir===basketballState.target){basketballState.hits++;$('#basketballFeedback').textContent='预判成功，完成抢断！'}else{basketballState.misses++;$('#basketballFeedback').textContent='突破方向判断失误。'}updateBasketballScore();setTimeout(()=>{if(basketballState.hits>=6)return finishBasketballGame();if(basketballState.misses>=3){basketballState.hits=0;basketballState.misses=0;$('#basketballFeedback').textContent='球权重置，重新争夺。';updateBasketballScore()}basketballState.locked=false;nextReaction()},430)}
function finishBasketballGame(){cancelAnimationFrame(basketballState.raf);clearTimeout(basketballState.timer);const stage=RDFZ.getStage(basketballState.stageId),first=!state.cleared.includes(stage.id);if(first){state.cleared.push(stage.id);state.gems+=stage.rewards?.gems||120}if(stage.id==='c3-4'&&!state.owned.includes('gjy'))state.owned.push('gjy');save();$('#basketballFeedback').textContent=stage.id==='c3-4'?'制胜球命中，AI控制正在解除……':'挑战完成，下一段球场路线已经解锁。';setTimeout(()=>{$('#basketballGame').classList.add('hidden');if(stage.id==='c3-4')openStageNarrative('post','basketball');else openChapterMap(3)},800)}
function leaveBasketballGame(){cancelAnimationFrame(basketballState.raf);clearTimeout(basketballState.timer);$('#basketballGame').classList.add('hidden');openChapterMap(3)}
let parkourState={active:false,lane:1,start:0,hits:0,spawnTimer:0,tickTimer:0,final:false};
function openParkourGame(){state.currentStageId='c7-1';state.chapter=7;$('#chapterMapScreen').classList.add('hidden');$('#parkourGame').classList.remove('hidden');parkourState={active:true,lane:1,start:Date.now(),hits:0,spawnTimer:0,tickTimer:0,final:false};updateRunner();parkourState.tickTimer=setInterval(updateParkour,250);spawnParkourObstacle()}
function updateRunner(){$('#runner').style.setProperty('--lane',parkourState.lane)}
function moveRunner(dir){if(!parkourState.active)return;if(parkourState.final&&parkourState.lane===2&&dir>0){parkourState.lane=3;updateRunner();finishParkour(true);return}parkourState.lane=Math.max(0,Math.min(2,parkourState.lane+dir));updateRunner()}
function spawnParkourObstacle(forceLane=null){if(!parkourState.active)return;const elapsed=(Date.now()-parkourState.start)/1000,duration=Math.max(1.25,3.3-elapsed*.018),lane=forceLane??Math.floor(Math.random()*3),o=document.createElement('div');o.className='track-obstacle';o.style.setProperty('--lane',lane);o.style.setProperty('--duration',`${duration}s`);o.textContent=['栏架','路锥','垫箱'][Math.floor(Math.random()*3)];$('#runTrack').append(o);setTimeout(()=>{if(parkourState.active&&parkourState.lane===lane&&!parkourState.final){parkourState.hits++;$('#parkourStatus').textContent=`撞上障碍！失误 ${parkourState.hits}/3`;if(parkourState.hits>=3)return finishParkour(false)}},duration*820);setTimeout(()=>o.remove(),duration*1000+100)}
function updateParkour(){if(!parkourState.active)return;const elapsed=(Date.now()-parkourState.start)/1000,left=Math.max(0,105-Math.floor(elapsed));$('#parkourTimer').textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;if(elapsed>=100&&!parkourState.final){parkourState.final=true;$('#runTrack').classList.add('final-lock');$('#parkourStatus').textContent='障碍密度达到峰值。';[0,1,2].forEach(l=>spawnParkourObstacle(l));return}if(!parkourState.final&&Date.now()-(parkourState.spawnTimer||0)>Math.max(430,1150-elapsed*6)){parkourState.spawnTimer=Date.now();spawnParkourObstacle()}}
function finishParkour(success){parkourState.active=false;clearInterval(parkourState.tickTimer);$$('.track-obstacle').forEach(x=>x.remove());$('#runTrack').classList.remove('final-lock');if(!success){$('#parkourStatus').textContent='被体统队伍抓住了，三秒后重新开始。';setTimeout(openParkourGame,1800);return}$('#parkourStatus').textContent='你从最右侧躲进厕所，成功逃过体育统练。';const stage=RDFZ.getStage('c7-1');if(!state.cleared.includes('c7-1')){state.cleared.push('c7-1');state.gems+=stage.rewards?.gems||120}save();setTimeout(()=>{$('#parkourGame').classList.add('hidden');openChapterMap(7)},1400)}
function leaveParkour(){parkourState.active=false;clearInterval(parkourState.tickTimer);$$('.track-obstacle').forEach(x=>x.remove());$('#parkourGame').classList.add('hidden');openChapterMap(7)}
function openDrivingGame(){state.currentStageId='c10-1';state.chapter=10;$('#chapterMapScreen').classList.add('hidden');$('#parkourGame').classList.remove('hidden');$('#parkourGame').classList.add('driving-mode');$('#parkourGame .eyebrow').textContent='SIMULATION DRIVE · ZERO TOLERANCE';$('#parkourGame h2').textContent='模拟驾驶教室';$('#parkourGame header p:not(.eyebrow)').textContent='使用 ← → 切换车道。速度远高于体育统练，任何一次碰撞都会导致演算失败。';$('#parkourStatus').textContent='驾驶模拟启动：碰撞容错为零。';parkourState={active:true,lane:1,start:Date.now(),hits:0,spawnTimer:0,tickTimer:0,final:false,labDrive:true};updateRunner();parkourState.tickTimer=setInterval(updateParkour,100);spawnParkourObstacle()}
const spawnParkourObstacleBeforeDriving=spawnParkourObstacle;
spawnParkourObstacle=function(forceLane=null){if(!parkourState.labDrive)return spawnParkourObstacleBeforeDriving(forceLane);if(!parkourState.active)return;const elapsed=(Date.now()-parkourState.start)/1000,duration=Math.max(.58,1.55-elapsed*.018),lane=forceLane??Math.floor(Math.random()*3),o=document.createElement('div');o.className='track-obstacle drive-obstacle';o.style.setProperty('--lane',lane);o.style.setProperty('--duration',`${duration}s`);o.textContent=['故障车','隔离墩','机械臂'][Math.floor(Math.random()*3)];$('#runTrack').append(o);setTimeout(()=>{if(parkourState.active&&parkourState.labDrive&&parkourState.lane===lane)finishParkour(false)},duration*810);setTimeout(()=>o.remove(),duration*1000+100)};
const updateParkourBeforeDriving=updateParkour;
