let libraryPuzzleState={stageId:'',step:0,sequence:[]};
function completePuzzleStage(stageId){const stage=RDFZ.getStage(stageId);if(!state.cleared.includes(stageId)){state.cleared.push(stageId);state.gems+=stage.rewards?.gems||120}save();$('#libraryPuzzleNote').innerHTML='<b>机关解除。</b> 进度已保存，新的路径已经开放。';setTimeout(()=>{$('#libraryPuzzle').classList.add('hidden');openChapterMap(stage.chapter)},900)}
function openBookSortingPuzzle(){libraryPuzzleState={stageId:'c5-1',step:0,sequence:[]};$('#chapterMapScreen').classList.add('hidden');$('#libraryPuzzle').classList.remove('hidden');$('#libraryPuzzleTitle').textContent='图书整理';$('#libraryPuzzleCopy').textContent='管理员留下的索书号全部被刮掉。书架铜牌上只有几条加法关系，按隐藏规则依次放回六本书。';$('#libraryPuzzleNote').textContent='提示：后一本书的编号，似乎与前两本有关。';const nums=[13,3,21,5,2,8];$('#libraryPuzzleScene').innerHTML=`<div class="book-rule">铜牌残文：Ⅱ + Ⅲ = Ⅴ　·　Ⅲ + Ⅴ = Ⅷ　·　……</div><div class="book-row">${nums.map(n=>`<button class="puzzle-book" data-n="${n}">${n}<small><br>无题藏书</small></button>`).join('')}</div><div class="sequence-display">归档顺序：<span id="bookSequence">—</span></div>`;$$('.puzzle-book').forEach(b=>b.onclick=()=>choosePuzzleBook(b))}
function choosePuzzleBook(button){const answer=[2,3,5,8,13,21],n=+button.dataset.n,index=libraryPuzzleState.sequence.length;if(n!==answer[index]){libraryPuzzleState.sequence=[];$$('.puzzle-book').forEach(x=>x.classList.remove('used'));$('#bookSequence').textContent='规则错误，书架自动复位';$('#libraryPuzzleNote').textContent='观察铜牌：每个编号都由前两个编号相加得到。';return}libraryPuzzleState.sequence.push(n);button.classList.add('used');$('#bookSequence').textContent=libraryPuzzleState.sequence.join(' → ');if(libraryPuzzleState.sequence.length===answer.length)completePuzzleStage('c5-1')}
function openArchivePuzzle(){libraryPuzzleState={stageId:'c5-2',step:0,sequence:[]};$('#chapterMapScreen').classList.add('hidden');$('#libraryPuzzle').classList.remove('hidden');$('#libraryPuzzleTitle').textContent='典藏馆';$('#libraryPuzzleCopy').textContent='没有战斗。三件馆藏彼此提供线索：先解开数列星盘，再用灵魂镜确定方向，最后让黄铜天平恢复平衡。';renderArchiveMechanism()}
function renderArchiveMechanism(){const s=libraryPuzzleState.step,scene=$('#libraryPuzzleScene'),note=$('#libraryPuzzleNote');if(s===0){scene.innerHTML='<div class="mechanism"><div class="device">1·1·2<br>3·5·8</div><div><h3>第一重 · 数列星盘</h3><p>星盘边缘刻着“下一齿承受前两齿之和”。13之后应转到哪一格？</p><button data-answer="21">21</button><button data-answer="26">26</button><button data-answer="34">34</button></div></div>';note.textContent='道具：缺齿星盘、十三号铜钥。'}else if(s===1){scene.innerHTML='<div class="mechanism"><div class="device">◉</div><div><h3>第二重 · 灵魂镜</h3><p>镜中四个影子只有一个与现实动作相反。馆藏卡写着：“日落处的灵魂为你指路。”</p><button data-answer="东">东</button><button data-answer="西">西</button><button data-answer="北">北</button></div></div>';note.textContent='道具：蒙尘灵魂镜、会自行转动的罗盘。'}else if(s===2){scene.innerHTML='<div class="mechanism"><div class="device">⚖</div><div><h3>第三重 · 黄铜天平</h3><p>左盘放着编号5的封蜡。右盘必须用两件馆藏配平；它们的重量分别刻在底部。</p><button data-answer="2+3">墨水瓶 2 ＋ 羽毛笔 3</button><button data-answer="1+3">钥匙 1 ＋ 羽毛笔 3</button><button data-answer="2+4">墨水瓶 2 ＋ 眼球标本 4</button></div></div>';note.textContent='道具：黄铜天平、黑墨水瓶、白羽毛笔、封蜡。'}else{scene.innerHTML='<div class="blood-letter">所有智慧都是人类的智慧，\n所有的灵魂将为你指明方向。\n怀疑<b>████</b>，但不要与她为敌。</div><button id="takeBloodLetter" class="primary-btn">收起血书</button>';note.textContent='关键剧情道具：血书。纸张仍然温热，被涂抹的名字无法辨认。';$('#takeBloodLetter').onclick=()=>{state.inventory.bloodLetter=true;completePuzzleStage('c5-2')};return}$$('#libraryPuzzleScene button').forEach(b=>b.onclick=()=>solveArchiveChoice(b.dataset.answer))}
function solveArchiveChoice(answer){const correct=['21','西','2+3'][libraryPuzzleState.step];if(answer!==correct){$('#libraryPuzzleNote').textContent='机关发出沉闷的回响，又恢复了原位。线索不在猜测，而在上一件馆藏。';return}libraryPuzzleState.step++;renderArchiveMechanism()}
function openReportHallStory(){openStageNarrative('pre','reportHall')}
const requiredTeamSize=()=>state.currentStageId==='c2-1'||state.currentStageId==='c8-6'?1:state.currentStageId==='c6-2'?2:state.currentStageId==='c10-3'?10:5;
function selectCampaignStage(stageId){const stage=RDFZ.getStage(stageId),chapter=campaignChapters[(stage?.chapter||1)-1],index=chapter?.stages.findIndex(s=>s.id===stageId)??-1;if(!stage||index<0||!stageUnlocked(chapter,index))return;state.currentStageId=stageId;state.chapter=stage.chapter;if(stageId==='c5-1'){openBookSortingPuzzle();return}if(stageId==='c5-2'){openArchivePuzzle();return}if(stageId==='c6-4'){openReportHallStory();return}if(stageId==='c3-2'||stageId==='c3-3'){openBasketballGame(stageId);return}if(stageId==='c3-4'){openStageNarrative('pre','basketball');return}if(state.owned.length<requiredTeamSize()){$('#chapterMapScreen').classList.add('hidden');openSummon();return}if(stageId==='c5-4'){openStageNarrative('pre','libraryDog');return}if(stageId==='c4-2'){openStageNarrative('pre','centralLawn');return}if(stageId==='c4-4'){openStageNarrative('pre','ancientTree');return}if(stageId==='c1-6'){openStageNarrative('pre');return}if(stageId==='c2-2'){openStageNarrative('pre','garden');return}if(stageId==='c2-6'){openStageNarrative('pre','rooftop');return}openFormation()}
function openFormation(){$('#homeScreen').classList.add('hidden');$('#chapterMapScreen').classList.add('hidden');$('#campaignMapScreen').classList.add('hidden');$('#formationScreen').classList.remove('hidden');const limit=requiredTeamSize(),saved=limit===10?(state.savedLabTeamIds||[]):(state.savedTeamIds||[]),valid=saved.filter(id=>state.owned.includes(id)&&heroes.some(h=>h.id===id));formationSelection=state.currentStageId==='c8-6'&&state.specialPhase!==2&&state.owned.includes('haq')?['haq']:[...new Set(valid)].slice(0,limit);const copy=$('.formation-head p:not(.eyebrow)');if(copy)copy.textContent=state.currentStageId==='c8-6'?'内讧第一阶段只能由何安淇独自迎战强化珈乐。':state.currentStageId==='c11-4'?'选择五名首发伙伴。其余所有已解锁英雄会依照图鉴顺序加入替补席，阵亡后自动补位。':limit===10?'天文台远征可选择十名伙伴：前五名首发，后五名按顺序作为替补，首发阵亡后立即补位。':limit===1?'玻璃绿植房为单人奖励关，只能选择一名伙伴出战。':limit===2?'二层羊汤只允许两名伙伴出战；战斗中及时拾取掉落的羊汤。':'从已解锁伙伴中选择五人。选择顺序即为 1–5 号位。';renderFormation()}
function renderFormation(){const limit=requiredTeamSize(),chosen=formationSelection.map(id=>heroes.find(h=>h.id===id)).filter(Boolean).map(scaledHero);$('#formationSlots').innerHTML=Array.from({length:limit},(_,i)=>{const h=chosen[i];return `<div class="formation-slot ${h?'':'empty'}" data-pos="${i+1}">${h?`<div class="slot-art" style="--art:${spriteArt(h.id)}"></div><b>${h.name}${h.upgradeLevel?` +${h.upgradeLevel}`:''}</b>`:''}</div>`}).join('');const available=state.owned.map(id=>heroes.find(h=>h.id===id)).filter(Boolean).map(scaledHero);$('#formationRoster').innerHTML=available.map(h=>`<button class="formation-choice ${formationSelection.includes(h.id)?'selected':''}" data-id="${h.id}" data-art-src="${heroSource(h.id)}"><div class="choice-art"></div><div class="choice-info"><b>${h.name}${h.upgradeLevel?` +${h.upgradeLevel}`:''}</b><span>${h.rank}级 · 【${h.role}】 · ${h.pos}号位 · 全属性 +${h.upgradeLevel*10}%</span></div></button>`).join('');RDFZAssets.observe($('#formationRoster'));$$('.formation-choice').forEach(b=>b.onclick=()=>toggleFormation(b.dataset.id));$('#formationCount').textContent=`已选择 ${chosen.length} / ${limit}`;$('#formationPower').textContent=Math.round(chosen.reduce((n,h)=>n+h.hp/10+h.atk*5+(h.def||0)*2,0)).toLocaleString();$('#confirmFormation').disabled=chosen.length!==limit}
function toggleFormation(id){const limit=requiredTeamSize(),i=formationSelection.indexOf(id);if(i>=0)formationSelection.splice(i,1);else if(formationSelection.length<limit)formationSelection.push(id);renderFormation()}
function recommendFormation(){const limit=requiredTeamSize(),score=h=>h.hp/10+h.atk*5+(h.def||0)*2+(h.rank==='S'?5000:0);formationSelection=state.owned.map(id=>heroes.find(h=>h.id===id)).filter(Boolean).map(scaledHero).sort((a,b)=>score(b)-score(a)).slice(0,limit).map(h=>h.id);if(state.currentStageId==='c1-6'&&state.owned.includes('hyb')&&!formationSelection.includes('hyb'))formationSelection[4]='hyb';renderFormation()}
function confirmFormation(){const limit=requiredTeamSize();if(formationSelection.length!==limit)return;if(state.currentStageId==='c1-6'&&!formationSelection.includes('hyb')){$('#formationCount').textContent='本关必须让黄艺博出战以破解无敌屏障';return}if(state.currentStageId==='c8-6'&&state.specialPhase!==2&&!formationSelection.includes('haq')){$('#formationCount').textContent='第一阶段只能使用何安淇';return}if(limit===5)state.savedTeamIds=[...formationSelection];if(state.currentStageId==='c11-4'){const reserveIds=state.owned.filter(id=>!formationSelection.includes(id)&&heroes.some(h=>h.id===id));state.savedAdminTeamIds=[...formationSelection,...reserveIds];state.team=formationSelection.map((id,i)=>({...cloneHero(heroes.find(h=>h.id===id)),pos:i+1}));state.reserves=reserveIds.map(id=>cloneHero(heroes.find(h=>h.id===id)));state.fallenCount=0}else if(limit===10){state.savedLabTeamIds=[...formationSelection];state.team=formationSelection.slice(0,5).map((id,i)=>({...cloneHero(heroes.find(h=>h.id===id)),pos:i+1}));state.reserves=formationSelection.slice(5).map(id=>cloneHero(heroes.find(h=>h.id===id)));state.fallenCount=0}else{state.team=formationSelection.map((id,i)=>({...cloneHero(heroes.find(h=>h.id===id)),pos:i+1}));state.reserves=[]}applyTeamSynergies();$('#formationScreen').classList.add('hidden');$('#app').classList.remove('hidden');save();enterBattle()}
function pauseBattle(){if(!state.started)return;state.paused=true;RDFZ.emit('battlePause',{});$('#pauseScreen').classList.remove('hidden')}
function resumeBattle(){state.paused=false;RDFZ.emit('battlePause',{});$('#pauseScreen').classList.add('hidden')}
function returnToHome(){save();sessionStorage.setItem('rdfz-return-home','1');location.reload()}
const storyRecruitHeroes=new Set(['lzy','hyb','tuanzi','jiale','lcr','hec','gjy','lsy','youn','lyk','xzh','pyh','nailin','qmr','ruishou','ssk']);
const postJuniorRecruitHeroes=new Set(['bella','leiyu','qunzhu']);
function recruitPool(){const unlocked=chapterComplete(campaignChapters[7]);return heroes.filter(h=>(!storyRecruitHeroes.has(h.id)||state.owned.includes(h.id))&&(!postJuniorRecruitHeroes.has(h.id)||unlocked||state.owned.includes(h.id)))}
function rollOne(forceA=false,exclude=[]){let r=Math.random(),rank=forceA?'A':r<.06?'S':r<.36?'A':'B';const blocked=new Set(exclude),allowed=recruitPool().filter(h=>!blocked.has(h.id));let pool=rank==='S'?allowed.filter(h=>h.rank==='S'):rank==='A'?allowed.filter(h=>h.rank==='A'):allowed;if(!pool.length)pool=allowed;if(!pool.length)pool=heroes.filter(h=>!blocked.has(h.id));return pool[Math.floor(Math.random()*pool.length)]}
function summon(count){const cost=count===10?2700:300;if(!state.unlimitedGems&&state.gems<cost){$('#summonResult').classList.remove('hidden');$('#pullCards').innerHTML='<div style="padding:50px;color:#f2c761">召唤石不足，完成主线关卡可继续获得。</div>';return}if(!state.unlimitedGems)state.gems-=cost;let pulls;if(count===10&&state.firstTen){pulls=[heroes[0],heroes[1],heroes[2],heroes[4],heroes[5],...Array.from({length:5},(_,i)=>rollOne(i===4))];state.firstTen=false}else pulls=Array.from({length:count},(_,i)=>rollOne(count===10&&i===9));const prior=new Set(state.owned),upgraded=[];pulls.forEach(h=>{if(state.owned.includes(h.id)){const levels=grantHeroFragments(h.id,20);if(levels)upgraded.push(`${h.name} +${heroUpgradeLevel(h.id)}`)}else state.owned.push(h.id)});state.pity=Math.max(0,state.pity-count);if(pulls.some(h=>h.rank==='S'))state.pity=30;$('#pullCards').innerHTML=pulls.map((h,i)=>`<article class="pull-card ${h.rank} ${prior.has(h.id)?'duplicate':''}" style="animation-delay:${i*.07}s;--art:${spriteArt(h.id)}"><div class="pull-art"></div><strong>${h.name}${heroUpgradeLevel(h.id)?` +${heroUpgradeLevel(h.id)}`:''}</strong><span>${h.rank}级 · ${h.role}</span></article>`).join('')+(upgraded.length?`<div style="width:100%;text-align:center;color:#f2c761">强化成功：${upgraded.join('、')} · 全属性永久提升</div>`:'');$('#summonResult').classList.remove('hidden');updateHub();RDFZ.emit('summon',{count,pulls:pulls.map(h=>h.id),upgraded});save()}
function openRoster(){$('#homeScreen').classList.add('hidden');$('#rosterScreen').classList.remove('hidden');renderRoster()}
function renderRoster(){const owned=new Set(state.owned);$('#rosterGrid').innerHTML=heroes.map(base=>{const h=scaledHero(base);return `<button class="roster-card ${owned.has(h.id)?'':'locked'}" data-hero="${h.id}" data-art-src="${heroSource(h.id)}"><div class="roster-art"></div><div class="roster-info"><b>${h.name}${h.upgradeLevel?` +${h.upgradeLevel}`:''}</b><span>${h.rank}级 · 【${h.role}】 · ${owned.has(h.id)?`${h.trait} · 全属性 +${h.upgradeLevel*10}%`:'尚未获得 · 点击查看图鉴'}</span></div></button>`}).join('');RDFZAssets.observe($('#rosterGrid'));$$('.roster-card').forEach(b=>b.onclick=()=>openHeroDetail(b.dataset.hero));autoBuildTeam();$('#teamDock').innerHTML=state.team.map(h=>`<div class="dock-hero" title="${h.name}" style="--art:${spriteArt(h.id,'thumb')}"></div>`).join('');updateHub()}
function openHeroDetail(id){const base=heroes.find(x=>x.id===id);if(!base)return;const h=scaledHero(base),fragments=state.inventory.fragments?.[id]||0;RDFZAssets.background($('#heroDetailArt'),heroSource(h.id),{property:'--art'});$('#detailRank').textContent=`${h.rank}级伙伴 · 【${h.role}】 · ${h.pos}号位 · 强化 +${h.upgradeLevel}`;$('#detailName').textContent=h.name;$('#detailLore').textContent=`${h.lore||h.trait}｜碎片 ${fragments}/100；每次强化使基础全属性永久增加 10%。`;$('#detailStats').innerHTML=`<div><span>生命</span><b>${h.hp}</b></div><div><span>攻击</span><b>${h.atk}</b></div><div><span>防御</span><b>${h.def||0}</b></div>`;$('#detailSkills').innerHTML=h.skills.length?h.skills.map((s,i)=>`<article><i>${i+1}</i><div><b>${s[0]}</b><span>消耗 ${s[1]} 技能星</span><p>${s[2]}</p></div></article>`).join(''):'<article><i>普</i><div><b>普通攻击</b><span>无技能</span><p>只能进行普通攻击；初始获得 10000 护盾。</p></div></article>';$('#heroDetail').classList.remove('hidden')}
const tutorialSteps=[
 {title:'欢迎来到 RDFZ 2024级风云',text:'这是一款校园题材的策略卡牌游戏。通过招募伙伴、编成阵容和挑战关卡，逐步夺回被失控 AI 占领的校园。',diagram:'<b>招募伙伴 → 编成队伍 → 挑战关卡 → 解锁剧情</b>'},
 {title:'伙伴与稀有度',text:'伙伴分为 S、A、B 三档。S 级更为稀有，但不同定位的伙伴都能在阵容中发挥作用。',diagram:'<span class="tier">S</span><span class="tier">A</span><span class="tier">B</span>'},
 {title:'技能与星能',text:'每位伙伴有三个技能。释放技能会消耗技能星；普通攻击不消耗星能。每个新回合，全队都会恢复技能星。',diagram:'<span class="element">✦3</span><span class="element">✦5</span><span class="element">✦8</span>'},
 {title:'五人位置',text:'队伍共有五个位置。1 号位通常最先承受攻击，2、3 号位负责输出，4、5 号位提供辅助与收割。',diagram:'<div class="positions"><i>4</i><i>2</i><i></i><i>5</i><i>3</i><i>1</i></div>'},
 {title:'伤害与五行',text:'伤害分为物理伤害和金、木、水、火、土五种属性伤害。护盾会优先吸收伤害，治疗则恢复伙伴生命。',diagram:'<span class="element" style="color:#e9ca70">金</span><span class="element" style="color:#6fd38a">木</span><span class="element" style="color:#63c9ff">水</span><span class="element" style="color:#ff6b4e">火</span><span class="element" style="color:#c99b70">土</span>'},
 {title:'开始新的冒险',text:'先前往“招募”完成首次十连，系统会确保你获得足以组成五人队的伙伴。然后回到主页，进入主线关卡。',diagram:'<b>招募伙伴 → 自动编队 → 进入冒险 → 解锁剧情</b>'}
];
let tutorialIndex=0;
function openTutorial(){tutorialIndex=0;$('#tutorialScreen').classList.remove('hidden');renderTutorial()}
function renderTutorial(){const s=tutorialSteps[tutorialIndex];$('#tutorialProgress').textContent=`${tutorialIndex+1} / ${tutorialSteps.length}`;$('#tutorialTitle').textContent=s.title;$('#tutorialText').textContent=s.text;$('#tutorialDiagram').innerHTML=s.diagram;$('#nextTutorial').textContent=tutorialIndex===tutorialSteps.length-1?'完成教程':'下一步'}
function finishTutorial(){state.tutorialDone=true;$('#tutorialScreen').classList.add('hidden');save()}
function openBag(){$('#homeScreen').classList.add('hidden');$('#bagScreen').classList.remove('hidden');const fragments=Object.values(state.inventory.fragments||{}).reduce((a,b)=>a+b,0);const items=[['◆','召唤石',state.gems,'用于招募伙伴'],['✦','招募券',state.inventory.tickets||3,'可代替召唤石单抽'],['⚡','体力',state.inventory.energy||96,'挑战主线关卡'],['◈','伙伴碎片',fragments,'每 100 个自动强化对应伙伴'],['书','经验笔记',12,'提升伙伴等级'],['印','升阶徽章',4,'伙伴突破材料'],['箱','随机礼盒',2,'开启获得随机资源']];if(state.inventory.bloodLetter)items.push(['血','典藏馆血书',1,'怀疑████，但不要与她为敌']);const resources=items.map(x=>`<article class="bag-item"><div class="item-icon">${x[0]}</div><b>${x[1]}</b><small>${x[3]}</small><em>× ${x[2]}</em></article>`);const heroFragments=state.owned.map(id=>heroes.find(h=>h.id===id)).filter(Boolean).map(h=>{const amount=state.inventory.fragments?.[h.id]||0,level=heroUpgradeLevel(h.id);return `<article class="bag-item"><div class="item-icon">${h.name[0]}</div><b>${h.name}碎片</b><small>${amount}/100 · 强化 +${level} · 全属性 +${level*10}%</small><em>× ${amount}</em></article>`});$('#bagGrid').innerHTML=[...resources,...heroFragments].join('')}
function openStories(){$('#homeScreen').classList.add('hidden');$('#storyScreen').classList.remove('hidden');const stories=RDFZ.list('stories');$('#storyList').innerHTML=stories.map(s=>{const unlocked=s.chapter<=state.chapter;return `<button class="story-card ${unlocked?'':'locked'}" data-story="${s.id}" ${unlocked?'':'disabled'}><span>第 ${s.chapter} 章</span><b>${unlocked?s.title:'尚未解锁'}</b><small>${unlocked?s.summary:`通关第 ${s.chapter-1} 章后解锁`}</small></button>`}).join('');$$('.story-card:not(.locked)').forEach(b=>b.onclick=()=>readStory(b.dataset.story))}
let activeStory,storyLineIndex=0;
function readStory(id){activeStory=RDFZ.getStory(id);storyLineIndex=0;$('#storyReader').classList.remove('hidden');$('#storyChapter').textContent=`CHAPTER ${String(activeStory.chapter).padStart(2,'0')}`;$('#storyTitle').textContent=activeStory.title;renderStoryLine();if(!state.storySeen.includes(id)){state.storySeen.push(id);save()}}
function renderStoryLine(){$('#storyLine').textContent=activeStory.lines[storyLineIndex];$('#nextStory').textContent=storyLineIndex===activeStory.lines.length-1?'结束回忆':'继续'}
